export function greet(req, res) {
  const name = req.body?.name;
  if (typeof name !== 'string' || name === '') {
    return res.status(400).json({ error: { code: 'VALIDATION', message: 'name is required' } });
  }
  res.status(200).json({ message: `Hello, ${name}!` });
}

