bootforge/express-api/handlers/handler-b.solution:
export function respondWith(res, result) {
  if (result.ok) {
    res.status(result.status ?? 200).json({ data: result.data });
  } else {
    res.status(result.status).json({ error: { code: result.code, message: result.message } });
  }
}

