bootforge/express-api/handlers/crud-hand.solution:
export function makeUserHandlers(store) {
  const notFound = (res, id) =>
    res.status(404).json({ error: { code: 'NOT_FOUND', message: `user ${id} not found` } });
  return {
    list(req, res) {
      res.status(200).json({ data: [...store.values()] });
    },
    get(req, res) {
      const user = store.get(req.params.id);
      if (!user) return notFound(res, req.params.id);
      res.status(200).json({ data: user });
    },
    create(req, res) {
      const name = req.body?.name;
      if (typeof name !== 'string' || name === '') {
        return res.status(400).json({ error: { code: 'VALIDATION', message: 'name is required' } });
      }
      let max = 0;
      for (const key of store.keys()) max = Math.max(max, Number(key));
      const id = String(max + 1);
      const user = { id, name };
      store.set(id, user);
      res.status(201).json({ data: user });
    },
    update(req, res) {
      const existing = store.get(req.params.id);
      if (!existing) return notFound(res, req.params.id);
      const updated = { ...existing };
      if (req.body.name !== undefined) updated.name = req.body.name;
      if (req.body.email !== undefined) updated.email = req.body.email;
      store.set(req.params.id, updated);
      res.status(200).json({ data: updated });
    },
    remove(req, res) {
      if (!store.delete(req.params.id)) return notFound(res, req.params.id);
      res.status(204);
    },
  };
}

