    ForbiddenError: { status: 403, code: 'FORBIDDEN' },
    NotFoundError: { status: 404, code: 'NOT_FOUND' },
    ConflictError: { status: 409, code: 'CONFLICT' },
  };
  const wrap = (handler) => (req, res) => {
    try {
      handler(req, res);
    } catch (err) {
      const hit = table[err.name];
      if (!hit) {
        return res.status(500).json({ error: { code: 'INTERNAL', message: 'internal server error' } });
      }
      res.status(hit.status).json({ error: { code: hit.code, message: err.message } });
    }
  };
  const out = {};
  for (const [key, handler] of Object.entries(handlers)) {
    out[key] = wrap(handler);
  }
  return out;
}

