export function makeRateLimiter(state, limit) {
  return (req, res, next) => {
    const client = req.headers['x-client-id'];
    if (typeof client !== 'string' || client === '') {
      return res.status(400).json({ error: { code: 'BAD_REQUEST', message: 'x-client-id header required' } });
    }
    state[client] = (state[client] ?? 0) + 1;
    if (state[client] > limit) {
      return res.status(429).json({ error: { code: 'RATE_LIMITED', message: 'too many requests' } });
    }
    next();
  };
}

