export function sortTodos(todos, sortValue) {
  const copy = [...todos];
  if (typeof sortValue !== 'string' || sortValue === '') return copy;
  const desc = sortValue.startsWith('-');
  const field = desc ? sortValue.slice(1) : sortValue;
  if (!['title', 'priority', 'id'].includes(field)) return copy;
  copy.sort((a, b) => {
    if (a[field] < b[field]) return desc ? 1 : -1;
    if (a[field] > b[field]) return desc ? -1 : 1;
    return 0;
  });
  return copy;
}

