export function makeCreateTodo(todos) {
  return (req, res) => {
    const body = req.body ?? {};
    const errors = [];
    if (body.title === undefined || body.title === '') {
      errors.push('title is required');
    } else if (typeof body.title !== 'string') {
      errors.push('title must be a string');
    } else if (body.title.length > 100) {
      errors.push('title must be at most 100 characters');
    }
    if (body.priority !== undefined) {
      if (!Number.isInteger(body.priority) || body.priority < 1 || body.priority > 5) {
        errors.push('priority must be an integer between 1 and 5');
      }
    }
    if (errors.length > 0) {
      return res.status(400).json({
        error: { code: 'VALIDATION', message: 'validation failed', details: errors },
      });
    }
    let max = 0;
    for (const t of todos) max = Math.max(max, t.id);
    const todo = { id: max + 1, title: body.title, done: false, priority: body.priority ?? 3 };
    todos.push(todo);
    res.status(201).json({ data: todo });
  };
}

