export function makeTodosApi(todos, usersByToken) {
  const authenticate = (req) => {
    const value = req.headers.authorization;
    const parts = typeof value === 'string' ? value.split(' ') : [];
    if (parts.length !== 2 || parts[0] !== 'Bearer' || parts[1] === '') return null;
    return usersByToken[parts[1]] ?? null;
  };
  const unauthorized = (res) =>
    res.status(401).json({ error: { code: 'UNAUTHORIZED', message: 'authentication required' } });
  return {
    list(req, res) {
      const user = authenticate(req);
      if (!user) return unauthorized(res);
      const data =
        req.query.open === 'true' ? todos.filter((t) => t.done === false) : todos;
      res.status(200).json({ data });
    },
    create(req, res) {
      const user = authenticate(req);
      if (!user) return unauthorized(res);
      if (!['editor', 'admin'].includes(user.role)) {
        return res.status(403).json({
          error: { code: 'FORBIDDEN', message: 'requires one of: editor, admin' },
        });
      }
      const title = req.body?.title;
      if (typeof title !== 'string' || title === '') {
        return res.status(400).json({ error: { code: 'VALIDATION', message: 'title is required' } });
      }
      let max = 0;
      for (const t of todos) max = Math.max(max, t.id);
      const todo = { id: max + 1, title, done: false, priority: 3, createdBy: user.id };
      todos.push(todo);
      res.status(201).json({ data: todo });
    },
  };
}
